SELECT EXISTS(
    SELECT 1
    FROM child_parent cp
    INNER JOIN member m
        ON m.member_id = cp.member_id
    WHERE cp.child_id = #{childId}
      AND cp.member_id = #{memberId}
      AND m.status = 'ACTIVE'
)

SELECT

FROM time_capsule tc
INNER JOIN financial_account fa
    ON fa.financial_account_id = tc.financial_account_id
LEFT JOIN financial_goal_template fgt
    ON fgt.financial_goal_template_id = fa.financial_goal_template_id
WHERE tc.child_id = #{childId}

    AND tc.status = #{status}


    AND (
        tc.created_at < #{cursorAt}
        OR (
            tc.created_at = #{cursorAt}
            AND tc.time_capsule_id < #{cursorId}
        )
    )

ORDER BY tc.created_at DESC, tc.time_capsule_id DESC
LIMIT #{limit}

SELECT

FROM time_capsule tc
INNER JOIN financial_account fa
    ON fa.financial_account_id = tc.financial_account_id
LEFT JOIN financial_goal_template fgt
    ON fgt.financial_goal_template_id = fa.financial_goal_template_id
WHERE tc.child_id = #{childId}
  AND tc.expected_release_at >= #{calendarStart}
  AND tc.expected_release_at < #{calendarEnd}

    AND tc.status = #{status}


    AND (
        tc.expected_release_at > #{cursorAt}
        OR (
            tc.expected_release_at = #{cursorAt}
            AND tc.time_capsule_id > #{cursorId}
        )
    )

ORDER BY tc.expected_release_at ASC, tc.time_capsule_id ASC
LIMIT #{limit}
